import{_ as e,o as a,c as s,a3 as l}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Alterar sigilo de vários documentos de uma vez","description":"","frontmatter":{"title":"Alterar sigilo de vários documentos de uma vez","id":"eproc-sigilo-documentos-lote","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.7.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-sigilo-documentos-lote"}]]},"headers":[],"relativePath":"funcionalidades/eproc-sigilo-documentos-lote.md","filePath":"funcionalidades/eproc-sigilo-documentos-lote.md"}'),i={name:"funcionalidades/eproc-sigilo-documentos-lote.md"};function r(t,o,d,c,n,u){return a(),s("div",null,o[0]||(o[0]=[l('<h1 id="alterar-sigilo-de-varios-documentos-de-uma-vez" tabindex="-1">Alterar sigilo de vários documentos de uma vez <a class="header-anchor" href="#alterar-sigilo-de-varios-documentos-de-uma-vez" aria-label="Permalink to &quot;Alterar sigilo de vários documentos de uma vez&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na alteração de sigilo em bloco, o eproc exige escolher o nível de sigilo documento por documento. Este recurso acrescenta ao cabeçalho da coluna &quot;Sigilo documento&quot; uma lista que aplica o nível escolhido a todos os documentos marcados de uma vez.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de alteração de sigilo de documentos, no modo em bloco.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a alteração de sigilo em bloco dos documentos do processo.</li><li>Marque, na primeira coluna, os documentos que quer alterar.</li><li>No cabeçalho da coluna &quot;Sigilo documento&quot;, escolha o nível na nova lista. O nível é aplicado a todos os documentos marcados.</li><li>Confira e salve normalmente.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A lista do cabeçalho só oferece os níveis disponíveis em todas as linhas.</li><li>Só aparece no modo em bloco (a tela que tem o botão &quot;Alteração Individual&quot;).</li><li>O eproc não lista na alteração em bloco os documentos com sigilo acima do nível 1, como os de nível 3 dos processos migrados do PJe. Esses só podem ser alterados individualmente, documento por documento. Em processos migrados, a marca de <a href="./eproc-sigilo-nivel3-migrados">Apontar documentos com sigilo nível 3</a> leva direto a essa alteração.</li></ul>',11)]))}const h=e(i,[["render",r]]);export{p as __pageData,h as default};
